   150→// AssertCheckpointAdvanced asserts the checkpoint branch moved forward.
   151→func AssertCheckpointAdvanced(t *testing.T, s *RepoState) {
   152→	t.Helper()
   153→	after := GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")
   154→	assert.NotEqual(t, s.CheckpointBefore, after, "checkpoint branch did not advance")
   155→}
   156→
   157→// AssertCheckpointNotAdvanced asserts the checkpoint branch has NOT moved.
   158→func AssertCheckpointNotAdvanced(t *testing.T, s *RepoState) {
   159→	t.Helper()
   160→	after := GitOutput(t, s.Dir, "rev-parse", "entire/checkpoints/v1")
   161→	assert.Equal(t, s.CheckpointBefore, after, "checkpoint branch advanced unexpectedly")
   162→}
