   164→// AssertCheckpointIDFormat asserts the checkpoint ID is 12 lowercase hex chars.
   165→func AssertCheckpointIDFormat(t *testing.T, checkpointID string) {
   166→	t.Helper()
   167→	assert.Regexp(t, hexIDPattern, checkpointID,
   168→		"checkpoint ID %q should be 12 lowercase hex chars", checkpointID)
   169→}
