   171→// AssertHasCheckpointTrailer asserts the commit has an Entire-Checkpoint trailer,
   172→// validates its format, and returns its value.
   173→func AssertHasCheckpointTrailer(t *testing.T, dir string, ref string) string {
   174→	t.Helper()
   175→	trailer := GetCheckpointTrailer(t, dir, ref)
   176→	require.NotEmpty(t, trailer, "no Entire-Checkpoint trailer on %s", ref)
   177→	AssertCheckpointIDFormat(t, trailer)
   178→	return trailer
   179→}
