   200→// AssertCheckpointExists asserts that the checkpoint ID is mentioned on
   201→// the checkpoint branch and that its metadata.json exists in the tree.
   202→func AssertCheckpointExists(t *testing.T, dir string, checkpointID string) {
   203→	t.Helper()
   204→	out := GitOutput(t, dir, "log", "entire/checkpoints/v1", "--grep="+checkpointID, "--oneline")
   205→	assert.NotEmpty(t, out, "checkpoint %s not found on checkpoint branch", checkpointID)
   206→
   207→	path := CheckpointPath(checkpointID) + "/metadata.json"
   208→	blob := "entire/checkpoints/v1:" + path
   209→	raw := gitOutputSafe(dir, "show", blob)
   210→	assert.NotEmpty(t, raw,
   211→		"checkpoint %s metadata not found at %s", checkpointID, path)
   212→}
