   214→// WaitForCheckpointExists polls until the checkpoint ID appears on the
   215→// checkpoint branch and its metadata.json is readable, or fails after timeout.
   216→func WaitForCheckpointExists(t *testing.T, dir string, checkpointID string, timeout time.Duration) {
   217→	t.Helper()
   218→	deadline := time.Now().Add(timeout)
   219→	for time.Now().Before(deadline) {
   220→		out := gitOutputSafe(dir, "log", "entire/checkpoints/v1", "--grep="+checkpointID, "--oneline")
   221→		if out != "" {
   222→			path := CheckpointPath(checkpointID) + "/metadata.json"
   223→			blob := "entire/checkpoints/v1:" + path
   224→			raw := gitOutputSafe(dir, "show", blob)
   225→			if raw != "" {
   226→				return
   227→			}
   228→		}
   229→		time.Sleep(200 * time.Millisecond)
   230→	}
   231→	t.Fatalf("checkpoint %s not found on checkpoint branch within %s", checkpointID, timeout)
   232→}
