   234→// AssertCommitLinkedToCheckpoint asserts the trailer exists AND the
   235→// checkpoint data exists on the checkpoint branch.
   236→func AssertCommitLinkedToCheckpoint(t *testing.T, dir string, ref string) {
   237→	t.Helper()
   238→	trailer := AssertHasCheckpointTrailer(t, dir, ref)
   239→	AssertCheckpointExists(t, dir, trailer)
   240→}
