   242→// AssertCheckpointHasSingleSession asserts checkpoint metadata has exactly one session.
   243→func AssertCheckpointHasSingleSession(t *testing.T, dir string, checkpointID string) {
   244→	t.Helper()
   245→	meta := ReadCheckpointMetadata(t, dir, checkpointID)
   246→	assert.Len(t, meta.Sessions, 1,
   247→		"expected 1 session in checkpoint %s, got %d", checkpointID, len(meta.Sessions))
   248→}
   249→
   250→// AssertCheckpointMetadataComplete asserts essential fields in checkpoint metadata are populated.
   251→func AssertCheckpointMetadataComplete(t *testing.T, dir string, checkpointID string) {
   252→	t.Helper()
   253→	meta := ReadCheckpointMetadata(t, dir, checkpointID)
   254→	assert.NotEmpty(t, meta.CLIVersion, "checkpoint %s: cli_version should be set", checkpointID)
   255→	assert.NotEmpty(t, meta.Strategy, "checkpoint %s: strategy should be set", checkpointID)
   256→	assert.NotEmpty(t, meta.Sessions, "checkpoint %s: should have at least 1 session", checkpointID)
   257→	assert.Equal(t, checkpointID, meta.CheckpointID,
   258→		"checkpoint metadata ID should match expected")
   259→}
