   261→// WaitForCheckpointAdvanceFrom polls until the checkpoint branch advances from
   262→// the given ref, or fails the test after timeout. Use this when waiting for a
   263→// second (or subsequent) checkpoint after recording the branch position.
   264→func WaitForCheckpointAdvanceFrom(t *testing.T, dir string, fromRef string, timeout time.Duration) {
   265→	t.Helper()
   266→	deadline := time.Now().Add(timeout)
   267→	for time.Now().Before(deadline) {
   268→		after := GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1")
   269→		if after != fromRef {
   270→			return
   271→		}
   272→		time.Sleep(200 * time.Millisecond)
   273→	}
   274→	t.Fatalf("checkpoint branch did not advance from %s within %s", fromRef[:8], timeout)
   275→}
   276→
   277→// WaitForSessionIdle polls the session state files in .git/entire-sessions/
   278→// until no session has phase "active", or fails the test after timeout.
   279→// This handles the race where an agent's prompt pattern appears in the TUI
   280→// before the turn-end hook has completed (transitioning ACTIVE → IDLE).
   281→func WaitForSessionIdle(t *testing.T, dir string, timeout time.Duration) {
   282→	t.Helper()
   283→	stateDir := filepath.Join(dir, ".git", "entire-sessions")
   284→	deadline := time.Now().Add(timeout)
   285→	for time.Now().Before(deadline) {
   286→		entries, err := os.ReadDir(stateDir)
   287→		if err != nil {
   288→			// Directory may not exist yet; keep polling
   289→			time.Sleep(200 * time.Millisecond)
   290→			continue
   291→		}
   292→		anyActive := false
   293→		for _, entry := range entries {
   294→			if entry.IsDir() || !strings.HasSuffix(entry.Name(), ".json") || strings.HasSuffix(entry.Name(), ".tmp") {
   295→				continue
   296→			}
   297→			data, err := os.ReadFile(filepath.Join(stateDir, entry.Name()))
   298→			if err != nil {
   299→				continue
   300→			}
   301→			var state struct {
   302→				Phase string `json:"phase"`
   303→			}
   304→			if err := json.Unmarshal(data, &state); err != nil {
   305→				continue
   306→			}
   307→			if state.Phase == "active" {
   308→				anyActive = true
   309→				break
   310→			}
   311→		}
   312→		if !anyActive {
   313→			return
   314→		}
   315→		time.Sleep(200 * time.Millisecond)
   316→	}
   317→	t.Fatalf("session(s) did not transition to idle within %s", timeout)
   318→}
   319→
   320→// AssertNoCheckpointTrailer asserts the commit does NOT have an Entire-Checkpoint trailer.
   321→func AssertNoCheckpointTrailer(t *testing.T, dir string, ref string) {
   322→	t.Helper()
   323→	trailer := GetCheckpointTrailer(t, dir, ref)
   324→	assert.Empty(t, trailer, "expected no Entire-Checkpoint trailer on %s, got %q", ref, trailer)
   325→}
   326→
   327→// AssertCheckpointFilesTouched asserts the checkpoint metadata lists exactly
   328→// the expected files in files_touched (order-independent).
   329→func AssertCheckpointFilesTouched(t *testing.T, dir string, checkpointID string, expected []string) {
   330→	t.Helper()
   331→	meta := ReadCheckpointMetadata(t, dir, checkpointID)
   332→	assert.ElementsMatch(t, expected, meta.FilesTouched,
   333→		"checkpoint %s: files_touched mismatch", checkpointID)
   334→}
   335→
   336→// AssertCheckpointFilesTouchedContains asserts files_touched contains a
   337→// specific file path (subset check, unlike the exact-match AssertCheckpointFilesTouched).
   338→func AssertCheckpointFilesTouchedContains(t *testing.T, dir string, checkpointID string, file string) {
   339→	t.Helper()
   340→	meta := ReadCheckpointMetadata(t, dir, checkpointID)
   341→	assert.Contains(t, meta.FilesTouched, file,
   342→		"checkpoint %s: files_touched should contain %s", checkpointID, file)
   343→}
   344→
   345→// AssertDistinctSessions asserts session metadata across checkpoints has unique session IDs.
   346→func AssertDistinctSessions(t *testing.T, dir string, checkpointIDs []string) {
   347→	t.Helper()
   348→	seen := map[string]bool{}
   349→	for _, cpID := range checkpointIDs {
   350→		sm := ReadSessionMetadata(t, dir, cpID, 0)
   351→		assert.False(t, seen[sm.SessionID],
   352→			"duplicate session_id %s across checkpoints", sm.SessionID)
   353→		seen[sm.SessionID] = true
   354→	}
   355→}
   356→
   357→// ValidateCheckpointDeep performs comprehensive validation of checkpoint metadata
   358→// on the checkpoint branch, including transcript JSONL validity, content hash
   359→// verification, and prompt content checking.
   360→func ValidateCheckpointDeep(t *testing.T, dir string, v DeepCheckpointValidation) {
   361→	t.Helper()
   362→
   363→	// Basic metadata validation
   364→	AssertCheckpointExists(t, dir, v.CheckpointID)
   365→	AssertCheckpointMetadataComplete(t, dir, v.CheckpointID)
   366→
   367→	if v.Strategy != "" {
   368→		meta := ReadCheckpointMetadata(t, dir, v.CheckpointID)
   369→		assert.Equal(t, v.Strategy, meta.Strategy,
   370→			"checkpoint %s: strategy mismatch", v.CheckpointID)
   371→	}
   372→
   373→	if len(v.FilesTouched) > 0 {
   374→		AssertCheckpointFilesTouched(t, dir, v.CheckpointID, v.FilesTouched)
   375→	}
   376→
   377→	path := CheckpointPath(v.CheckpointID)
   378→
   379→	// Validate session metadata exists and has checkpoint_id
   380→	sessionBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/metadata.json", path)
   381→	sessionRaw := gitOutputSafe(dir, "show", sessionBlob)
   382→	if assert.NotEmpty(t, sessionRaw, "session metadata should exist at %s", sessionBlob) {
   383→		var sessionMeta map[string]any
   384→		if assert.NoError(t, json.Unmarshal([]byte(sessionRaw), &sessionMeta)) {
   385→			assert.Equal(t, v.CheckpointID, sessionMeta["checkpoint_id"],
   386→				"session metadata checkpoint_id should match")
   387→			assert.NotEmpty(t, sessionMeta["created_at"], "session metadata should have created_at")
   388→		}
   389→	}
   390→
   391→	// Validate transcript is valid JSONL
   392→	transcriptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/full.jsonl", path)
   393→	transcriptRaw := gitOutputSafe(dir, "show", transcriptBlob)
   394→	if assert.NotEmpty(t, transcriptRaw, "transcript should exist at %s", transcriptBlob) {
   395→		lines := strings.Split(transcriptRaw, "\n")
   396→		nonEmpty := 0
   397→		for _, line := range lines {
   398→			if strings.TrimSpace(line) != "" {
   399→				nonEmpty++
   400→			}
   401→		}
   402→		assert.Positive(t, nonEmpty, "transcript should have at least one line")
   403→
   404→		for _, expected := range v.ExpectedTranscriptContent {
   405→			assert.Contains(t, transcriptRaw, expected,
   406→				"transcript should contain %q", expected)
   407→		}
   408→
   409→		// Validate content hash
   410→		hashBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/content_hash.txt", path)
   411→		hashRaw := gitOutputSafe(dir, "show", hashBlob)
   412→		if hashRaw != "" {
   413→			hash := sha256.Sum256([]byte(transcriptRaw))
   414→			expectedHash := "sha256:" + hex.EncodeToString(hash[:])
   415→			assert.Equal(t, expectedHash, strings.TrimSpace(hashRaw),
   416→				"content hash should match transcript SHA-256")
   417→		}
   418→	}
   419→
   420→	// Validate prompt.txt if expected prompts specified
   421→	if len(v.ExpectedPrompts) > 0 {
   422→		promptBlob := fmt.Sprintf("entire/checkpoints/v1:%s/0/prompt.txt", path)
   423→		promptRaw := gitOutputSafe(dir, "show", promptBlob)
   424→		for _, expected := range v.ExpectedPrompts {
   425→			assert.Contains(t, promptRaw, expected,
   426→				"prompt.txt should contain %q", expected)
   427→		}
   428→	}
   429→}
