   423→// interface and reports itself as external.
   424→func (s *RepoState) IsExternalAgent() bool {
   425→	ea, ok := s.Agent.(agents.ExternalAgent)
   426→	return ok && ea.IsExternalAgent()
   427→}
   428→
   429→// Send sends input to an interactive session and logs it to ConsoleLog.
   430→// Fails the test on error.
   431→func (s *RepoState) Send(t *testing.T, session agents.Session, input string) {
   432→	t.Helper()
   433→	s.ConsoleLog.WriteString("> send: " + input + "\n")
   434→	if err := session.Send(input); err != nil {
   435→		t.Fatalf("send failed: %v", err)
   436→	}
   437→}
   438→
   439→// PatchSettings merges extra keys into .entire/settings.json.
   440→func PatchSettings(t *testing.T, dir string, extra map[string]any) {
   441→	t.Helper()
   442→	path := filepath.Join(dir, ".entire", "settings.json")
   443→	data, err := os.ReadFile(path)
   444→	if err != nil {
   445→		t.Fatalf("read settings: %v", err)
   446→	}
   447→	var settings map[string]any
   448→	if err := json.Unmarshal(data, &settings); err != nil {
   449→		t.Fatalf("parse settings: %v", err)
   450→	}
   451→	for k, v := range extra {
   452→		settings[k] = v
   453→	}
   454→	out, err := json.MarshalIndent(settings, "", "  ")
   455→	if err != nil {
   456→		t.Fatalf("marshal settings: %v", err)
   457→	}
   458→	if err := os.WriteFile(path, out, 0o644); err != nil {
   459→		t.Fatalf("write settings: %v", err)
   460→	}
   461→}
   462→
   463→// EmptyDir returns the path to an empty temporary directory, cleaned up when
   464→// the test finishes. Useful as a cross-platform replacement for /dev/null in
   465→// git config paths like core.hooksPath (git on Windows cannot open NUL).
   466→func EmptyDir(t *testing.T) string {
   467→	t.Helper()
   468→	return t.TempDir()
   469→}
   470→
   471→// Git runs a git command in the given directory and fails the test if it
   472→// returns a non-zero exit code.
   473→func Git(t *testing.T, dir string, args ...string) {
   474→	t.Helper()
   475→
   476→	cmd := exec.Command("git", args...)
   477→	if dir != "" {
   478→		cmd.Dir = dir
   479→	}
   480→	cmd.Env = append(os.Environ(), "ENTIRE_TEST_TTY=0")
   481→
   482→	out, err := cmd.CombinedOutput()
   483→	if err != nil {
   484→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, out)
   485→	}
   486→}
   487→
   488→// GitOutput runs a git command in the given directory, returns its trimmed
   489→// stdout, and fails the test on error.
   490→func GitOutput(t *testing.T, dir string, args ...string) string {
   491→	t.Helper()
   492→
   493→	cmd := exec.Command("git", args...)
   494→	if dir != "" {
   495→		cmd.Dir = dir
   496→	}
   497→
   498→	out, err := cmd.Output()
   499→	if err != nil {
   500→		var stderr string
   501→		ee := &exec.ExitError{}
   502→		if errors.As(err, &ee) {
   503→			stderr = string(ee.Stderr)
   504→		}
   505→		t.Fatalf("git %s failed: %v\n%s", strings.Join(args, " "), err, stderr)
   506→	}
   507→
   508→	return strings.TrimSpace(string(out))
   509→}
   510→
   511→// NewCheckpointCommits returns the SHAs of commits added to the
   512→// entire/checkpoints/v1 branch since the test was set up, oldest first.
   513→func NewCheckpointCommits(t *testing.T, s *RepoState) []string {
   514→	t.Helper()
   515→
   516→	log := GitOutput(t, s.Dir, "log", "--reverse", "--format=%H", s.CheckpointBefore+"..entire/checkpoints/v1")
   517→	if log == "" {
   518→		return nil
   519→	}
   520→	return strings.Split(log, "\n")
   521→}
   522→
   523→// CheckpointIDs lists all checkpoint IDs from the tree at the tip of the
   524→// checkpoint branch. It parses the two-level directory structure
   525→// ({prefix}/{suffix}/metadata.json) and returns the concatenated IDs.
   526→func CheckpointIDs(t *testing.T, dir string) []string {
   527→	t.Helper()
   528→	out := gitOutputSafe(dir, "ls-tree", "-r", "--name-only", "entire/checkpoints/v1")
   529→	if out == "" {
   530→		return nil
   531→	}
   532→	seen := map[string]bool{}
   533→	var ids []string
   534→	for _, line := range strings.Split(strings.TrimSpace(out), "\n") {
   535→		// Match {prefix}/{suffix}/metadata.json (top-level, not session-level)
   536→		parts := strings.Split(line, "/")
   537→		if len(parts) == 3 && parts[2] == "metadata.json" {
   538→			id := parts[0] + parts[1]
   539→			if !seen[id] {
   540→				seen[id] = true
   541→				ids = append(ids, id)
   542→			}
   543→		}
   544→	}
   545→	return ids
   546→}
   547→
   548→// ReadCheckpointMetadata reads the checkpoint-level metadata.json from the
   549→// tip of the checkpoint branch for the given checkpoint ID.
   550→func ReadCheckpointMetadata(t *testing.T, dir string, checkpointID string) CheckpointMetadata {
   551→	t.Helper()
   552→
   553→	path := CheckpointPath(checkpointID) + "/metadata.json"
   554→	blob := "entire/checkpoints/v1:" + path
   555→
   556→	raw := GitOutput(t, dir, "show", blob)
   557→
   558→	var meta CheckpointMetadata
   559→	if err := json.Unmarshal([]byte(raw), &meta); err != nil {
   560→		t.Fatalf("unmarshal checkpoint metadata from %s: %v", blob, err)
   561→	}
   562→
   563→	return meta
   564→}
   565→
   566→// ReadSessionMetadata reads a session's metadata.json from the tip of the
   567→// checkpoint branch for the given checkpoint ID and session index.
   568→func ReadSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int) SessionMetadata {
   569→	t.Helper()
   570→
   571→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
   572→	blob := "entire/checkpoints/v1:" + path
   573→
   574→	raw := GitOutput(t, dir, "show", blob)
   575→
   576→	var meta SessionMetadata
   577→	if err := json.Unmarshal([]byte(raw), &meta); err != nil {
   578→		t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
   579→	}
   580→
   581→	return meta
   582→}
   583→
   584→// WaitForSessionMetadata polls until session metadata exists on the checkpoint
   585→// branch for the given checkpoint ID and session index, then returns it.
   586→// This handles the race where the checkpoint branch advances before session
   587→// metadata is fully committed.
   588→func WaitForSessionMetadata(t *testing.T, dir string, checkpointID string, sessionIndex int, timeout time.Duration) SessionMetadata {
   589→	t.Helper()
   590→
   591→	path := fmt.Sprintf("%s/%d/metadata.json", CheckpointPath(checkpointID), sessionIndex)
   592→	blob := "entire/checkpoints/v1:" + path
   593→
   594→	deadline := time.Now().Add(timeout)
   595→	for time.Now().Before(deadline) {
   596→		raw := gitOutputSafe(dir, "show", blob)
   597→		if raw != "" {
   598→			var meta SessionMetadata
   599→			if err := json.Unmarshal([]byte(raw), &meta); err != nil {
   600→				t.Fatalf("unmarshal session metadata from %s: %v", blob, err)
   601→			}
   602→			return meta
   603→		}
   604→		time.Sleep(500 * time.Millisecond)
   605→	}
   606→	t.Fatalf("session metadata %s did not appear within %s", blob, timeout)
   607→	return SessionMetadata{}
   608→}
   609→
   610→// SetupBareRemote creates a bare git repo, adds it as "origin", and pushes
   611→// the initial commit. Returns the bare repo path.
   612→func SetupBareRemote(t *testing.T, s *RepoState) string {
   613→	t.Helper()
   614→
   615→	var bareDir string
