package cli

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log/slog"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/osroot"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/validation"

	"github.com/go-git/go-git/v6"
)

// PrePromptState stores the state captured before a user prompt
type PrePromptState struct {
	SessionID      string   `json:"session_id"`
	Timestamp      string   `json:"timestamp"`
	UntrackedFiles []string `json:"untracked_files"`

	// TranscriptOffset is the unified transcript position when this state was captured.
	// For Claude Code (JSONL), this is the line count.
	// For Gemini CLI (JSON), this is the message count.
	// Zero means not set or session just started.
	TranscriptOffset int `json:"transcript_offset,omitempty"`

	// LastTranscriptIdentifier is the agent-specific identifier at the transcript position.
	// UUID for Claude Code, message ID for Gemini CLI. Optional metadata.
	LastTranscriptIdentifier string `json:"last_transcript_identifier,omitempty"`

	// Deprecated: StartMessageIndex is the old Gemini-specific field.
	// Migrated to TranscriptOffset on load.
	StartMessageIndex int `json:"start_message_index,omitempty"`

	// Deprecated: StepTranscriptStart is the old Claude-specific field.
	// Migrated to TranscriptOffset on load.
	StepTranscriptStart int `json:"step_transcript_start,omitempty"`

	// Deprecated: LastTranscriptLineCount is the oldest name for transcript position.
	// Migrated to TranscriptOffset on load.
	LastTranscriptLineCount int `json:"last_transcript_line_count,omitempty"`
}

// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
// This nil-vs-empty distinction lets DetectFileChanges know whether to skip new-file detection.
// When the receiver is non-nil but UntrackedFiles is nil (e.g., old state files deserialized with
// "untracked_files": null), returns an empty non-nil slice so that all current untracked files
// are correctly treated as new.
func (s *PrePromptState) PreUntrackedFiles() []string {
	if s == nil {
		return nil
	}
	if s.UntrackedFiles == nil {
		return []string{}
	}
	return s.UntrackedFiles
}

// normalizePrePromptState migrates deprecated fields after loading from JSON.
func (s *PrePromptState) normalizePrePromptState() {
	// Migrate the oldest field to the intermediate field first
	if s.StepTranscriptStart == 0 && s.LastTranscriptLineCount > 0 {
		s.StepTranscriptStart = s.LastTranscriptLineCount
	}
	s.LastTranscriptLineCount = 0

	// Migrate all deprecated fields to the unified TranscriptOffset
	if s.TranscriptOffset == 0 {
		if s.StepTranscriptStart > 0 {
			s.TranscriptOffset = s.StepTranscriptStart
		} else if s.StartMessageIndex > 0 {
			s.TranscriptOffset = s.StartMessageIndex
		}
	}
	s.StepTranscriptStart = 0
	s.StartMessageIndex = 0
}

// CapturePrePromptState captures current untracked files and transcript position before a prompt
// and saves them to a state file.
//
// The agent parameter is used to determine the transcript position via TranscriptAnalyzer.
// If the agent does not implement TranscriptAnalyzer, the transcript offset will be 0.
// The sessionRef parameter is optional — if empty, transcript position won't be captured.
//
// Works correctly from any subdirectory within the repository.
func CapturePrePromptState(ctx context.Context, ag agent.Agent, sessionID, sessionRef string) error {
	if sessionID == "" {
		sessionID = unknownSessionID
	}

	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID for pre-prompt state: %w", err)
	}

	// Get absolute path for tmp directory
	tmpDirAbs := resolveTmpDir(ctx)

	// Create tmp directory if it doesn't exist
	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create tmp directory: %w", err)
	}

	// Get list of untracked files (excluding .entire directory itself)
	untrackedFiles, err := getUntrackedFilesForState(ctx)
	if err != nil {
		return fmt.Errorf("failed to get untracked files: %w", err)
	}

	// Get transcript position using TranscriptAnalyzer if available
	var transcriptOffset int
	if analyzer, ok := agent.AsTranscriptAnalyzer(ag); ok && sessionRef != "" {
		pos, posErr := analyzer.GetTranscriptPosition(sessionRef)
		if posErr != nil {
			logging.Warn(logging.WithComponent(ctx, "state"), "failed to get transcript position",
				slog.String("error", posErr.Error()))
		} else {
			transcriptOffset = pos
		}
	}

	// Create state file using os.Root for traversal-resistant write
	state := PrePromptState{
		SessionID:        sessionID,
		Timestamp:        time.Now().UTC().Format(time.RFC3339),
		UntrackedFiles:   untrackedFiles,
		TranscriptOffset: transcriptOffset,
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal state: %w", err)
	}

	fileName := fmt.Sprintf("pre-prompt-%s.json", sessionID)
	root, err := os.OpenRoot(tmpDirAbs)
	if err != nil {
		return fmt.Errorf("failed to open tmp directory root: %w", err)
	}
	defer root.Close()

	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
		return fmt.Errorf("failed to write state file: %w", err)
	}

	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before prompt",
		slog.Int("untracked_files", len(untrackedFiles)),
		slog.Int("transcript_offset", transcriptOffset))
	return nil
}

// LoadPrePromptState loads previously captured state.
// Returns nil if no state file exists.
func LoadPrePromptState(ctx context.Context, sessionID string) (*PrePromptState, error) {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return nil, fmt.Errorf("invalid session ID for pre-prompt state: %w", err)
	}

	tmpDirAbs := resolveTmpDir(ctx)

	root, err := os.OpenRoot(tmpDirAbs)
	if err != nil {
		// Directory doesn't exist yet — no state file
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // already present in codebase
		}
		return nil, fmt.Errorf("failed to open tmp directory root: %w", err)
	}
	defer root.Close()

	fileName := fmt.Sprintf("pre-prompt-%s.json", sessionID)
	data, err := osroot.ReadFile(root, fileName)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // already present in codebase
		}
		return nil, fmt.Errorf("failed to read state file: %w", err)
	}

	var state PrePromptState
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
	}

	state.normalizePrePromptState()

	return &state, nil
}

// CleanupPrePromptState removes the state file after use
func CleanupPrePromptState(ctx context.Context, sessionID string) error {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID for pre-prompt state cleanup: %w", err)
	}

	tmpDirAbs := resolveTmpDir(ctx)

	root, err := os.OpenRoot(tmpDirAbs)
	if err != nil {
		if os.IsNotExist(err) {
			return nil // Directory doesn't exist, nothing to clean up
		}
		return fmt.Errorf("failed to open tmp directory root: %w", err)
	}
	defer root.Close()

	fileName := fmt.Sprintf("pre-prompt-%s.json", sessionID)
	return osroot.Remove(root, fileName) //nolint:wrapcheck // best-effort cleanup, caller adds context via wrapping function name
}

// FileChanges holds categorized file changes from git status.
type FileChanges struct {
	Modified []string // Modified or staged files
	New      []string // Untracked files (filtered if previouslyUntracked provided)
	Deleted  []string // Deleted files (staged or unstaged)
}

// DetectFileChanges returns categorized file changes from the current git status.
//
// previouslyUntracked controls new-file detection:
//   - nil: all untracked files go into New
//   - non-nil: only untracked files NOT in the pre-existing set go into New
//
// Modified includes both worktree and staging modified/added files.
// Deleted includes both staged and unstaged deletions.
// All results exclude .entire/ directory.
func DetectFileChanges(ctx context.Context, previouslyUntracked []string) (*FileChanges, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return nil, fmt.Errorf("failed to open repository: %w", err)
	}

	worktree, err := repo.Worktree()
	if err != nil {
		return nil, fmt.Errorf("failed to get worktree: %w", err)
	}

	status, err := worktree.Status()
	if err != nil {
		return nil, fmt.Errorf("failed to get status: %w", err)
	}

	// Build set of pre-existing untracked files for quick lookup
	var preExisting map[string]bool
	if previouslyUntracked != nil {
		preExisting = make(map[string]bool, len(previouslyUntracked))
		for _, f := range previouslyUntracked {
			preExisting[f] = true
		}
	}

	var changes FileChanges
	for file, st := range status {
		if paths.IsInfrastructurePath(file) {
			continue
		}

		switch {
		case st.Worktree == git.Untracked:
			if preExisting != nil {
				if !preExisting[file] {
					changes.New = append(changes.New, file)
				}
			} else {
				changes.New = append(changes.New, file)
			}
		case st.Worktree == git.Deleted || st.Staging == git.Deleted:
			changes.Deleted = append(changes.Deleted, file)
		case st.Worktree == git.Modified || st.Staging == git.Modified ||
			st.Worktree == git.Added || st.Staging == git.Added:
			changes.Modified = append(changes.Modified, file)
		}
	}

	return &changes, nil
}

// filterToUncommittedFiles removes files from the list that are already committed to HEAD
// with matching content. This prevents re-adding files that an agent committed mid-turn
// (already condensed by PostCommit) back to FilesTouched via SaveStep. Files not in
// HEAD or with different content in the working tree are kept. Fails open: if any git
// operation errors, returns the original list unchanged.
func filterToUncommittedFiles(ctx context.Context, files []string, repoRoot string) []string {
	if len(files) == 0 {
		return files
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return files // fail open
	}

	head, err := repo.Head()
	if err != nil {
		return files // fail open (empty repo, detached HEAD, etc.)
	}

	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return files // fail open
	}

	headTree, err := commit.Tree()
	if err != nil {
		return files // fail open
	}

	var result []string
	for _, relPath := range files {
		headFile, err := headTree.File(relPath)
		if err != nil {
			// File not in HEAD — it's uncommitted
			result = append(result, relPath)
			continue
		}

		// File is in HEAD — compare content with working tree
		absPath := filepath.Join(repoRoot, relPath)
		workingContent, err := os.ReadFile(absPath) //nolint:gosec // path from controlled source
		if err != nil {
			// Can't read working tree file (deleted?) — keep it
			result = append(result, relPath)
			continue
		}

		headContent, err := headFile.Contents()
		if err != nil {
			result = append(result, relPath)
			continue
		}

		if string(workingContent) != headContent {
			// Working tree differs from HEAD — uncommitted changes
			result = append(result, relPath)
		}
		// else: content matches HEAD — already committed, skip
	}

	return result
}

// FilterAndNormalizePaths converts absolute paths to relative and filters out
// infrastructure paths and paths outside the repo.
func FilterAndNormalizePaths(files []string, cwd string) []string {
	var result []string
	for _, file := range files {
		relPath := paths.ToRelativePath(file, cwd)
		if relPath == "" {
			continue // outside repo
		}
		if paths.IsInfrastructurePath(relPath) {
			continue // skip .entire directory
		}
		result = append(result, filepath.ToSlash(relPath))
	}
	return result
}

// mergeUnique appends elements from extra into base, skipping duplicates already in base.
func mergeUnique(base, extra []string) []string {
	if len(extra) == 0 {
		return base
	}
	seen := make(map[string]bool, len(base))
	for _, s := range base {
		seen[s] = true
	}
	for _, s := range extra {
		if !seen[s] {
			seen[s] = true
			base = append(base, s)
		}
	}
	return base
}

// resolveTmpDir returns the absolute path to the .entire/tmp directory,
// falling back to a relative path if the repo root can't be determined.
func resolveTmpDir(ctx context.Context) string {
	abs, err := paths.AbsPath(ctx, paths.EntireTmpDir)
	if err != nil {
		return paths.EntireTmpDir
	}
	return abs
}

// getUntrackedFilesForState returns a list of untracked files using go-git
// Excludes .entire directory
func getUntrackedFilesForState(ctx context.Context) ([]string, error) {
	repo, err := openRepository(ctx)
	if err != nil {
		return nil, err
	}

	worktree, err := repo.Worktree()
	if err != nil {
		return nil, err //nolint:wrapcheck // already present in codebase
	}

	status, err := worktree.Status()
	if err != nil {
		return nil, err //nolint:wrapcheck // already present in codebase
	}

	untrackedFiles := []string{}
	for file, st := range status {
		if st.Worktree == git.Untracked {
			// Exclude .entire directory
			if !paths.IsInfrastructurePath(file) {
				untrackedFiles = append(untrackedFiles, file)
			}
		}
	}

	return untrackedFiles, nil
}

// PreTaskState stores the state captured before a task execution
type PreTaskState struct {
	ToolUseID      string   `json:"tool_use_id"`
	Timestamp      string   `json:"timestamp"`
	UntrackedFiles []string `json:"untracked_files"`
}

// PreUntrackedFiles returns the untracked files list, or nil if the receiver is nil.
// See PrePromptState.PreUntrackedFiles for nil-vs-empty semantics.
func (s *PreTaskState) PreUntrackedFiles() []string {
	if s == nil {
		return nil
	}
	if s.UntrackedFiles == nil {
		return []string{}
	}
	return s.UntrackedFiles
}

// CapturePreTaskState captures current untracked files before a Task execution
// and saves them to a state file.
// Works correctly from any subdirectory within the repository.
func CapturePreTaskState(ctx context.Context, toolUseID string) error {
	if toolUseID == "" {
		return errors.New("tool_use_id is required")
	}

	if err := validation.ValidateToolUseID(toolUseID); err != nil {
		return fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
	}

	// Get absolute path for tmp directory
	tmpDirAbs := resolveTmpDir(ctx)

	// Create tmp directory if it doesn't exist
	if err := os.MkdirAll(tmpDirAbs, 0o750); err != nil {
		return fmt.Errorf("failed to create tmp directory: %w", err)
	}

	// Get list of untracked files (excluding .entire directory itself)
	untrackedFiles, err := getUntrackedFilesForState(ctx)
	if err != nil {
		return fmt.Errorf("failed to get untracked files: %w", err)
	}

	// Create state file using os.Root for traversal-resistant write
	state := PreTaskState{
		ToolUseID:      toolUseID,
		Timestamp:      time.Now().UTC().Format(time.RFC3339),
		UntrackedFiles: untrackedFiles,
	}

	data, err := jsonutil.MarshalIndentWithNewline(state, "", "  ")
	if err != nil {
		return fmt.Errorf("failed to marshal state: %w", err)
	}

	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
	root, err := os.OpenRoot(tmpDirAbs)
	if err != nil {
		return fmt.Errorf("failed to open tmp directory root: %w", err)
	}
	defer root.Close()

	if err := osroot.WriteFile(root, fileName, data, 0o600); err != nil {
		return fmt.Errorf("failed to write state file: %w", err)
	}

	logging.Debug(logging.WithComponent(ctx, "state"), "captured state before task",
		slog.Int("untracked_files", len(untrackedFiles)))
	return nil
}

// LoadPreTaskState loads previously captured task state.
// Returns nil if no state file exists.
func LoadPreTaskState(ctx context.Context, toolUseID string) (*PreTaskState, error) {
	if err := validation.ValidateToolUseID(toolUseID); err != nil {
		return nil, fmt.Errorf("invalid tool use ID for pre-task state: %w", err)
	}

	tmpDirAbs := resolveTmpDir(ctx)

	root, err := os.OpenRoot(tmpDirAbs)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // already present in codebase
		}
		return nil, fmt.Errorf("failed to open tmp directory root: %w", err)
	}
	defer root.Close()

	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
	data, err := osroot.ReadFile(root, fileName)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil //nolint:nilnil // already present in codebase
		}
		return nil, fmt.Errorf("failed to read state file: %w", err)
	}

	var state PreTaskState
	if err := json.Unmarshal(data, &state); err != nil {
		return nil, fmt.Errorf("failed to unmarshal state: %w", err)
	}

	return &state, nil
}

// CleanupPreTaskState removes the task state file after use
func CleanupPreTaskState(ctx context.Context, toolUseID string) error {
	if err := validation.ValidateToolUseID(toolUseID); err != nil {
		return fmt.Errorf("invalid tool use ID for pre-task state cleanup: %w", err)
	}

	tmpDirAbs := resolveTmpDir(ctx)

	root, err := os.OpenRoot(tmpDirAbs)
	if err != nil {
		if os.IsNotExist(err) {
			return nil // Directory doesn't exist, nothing to clean up
		}
		return fmt.Errorf("failed to open tmp directory root: %w", err)
	}
	defer root.Close()

	fileName := fmt.Sprintf("pre-task-%s.json", toolUseID)
	return osroot.Remove(root, fileName) //nolint:wrapcheck // best-effort cleanup, caller adds context via wrapping function name
}

// preTaskFilePrefix is the prefix for pre-task state files
const preTaskFilePrefix = "pre-task-"

// FindActivePreTaskFile finds an active pre-task file in .entire/tmp/ and returns
// the parent Task's tool_use_id. Returns ("", false) if no pre-task file exists.
// When multiple pre-task files exist (nested subagents), returns the most recently
// modified one.
// Works correctly from any subdirectory within the repository.
func FindActivePreTaskFile(ctx context.Context) (taskToolUseID string, found bool) {
	tmpDirAbs := resolveTmpDir(ctx)
	entries, err := os.ReadDir(tmpDirAbs)
	if err != nil {
		return "", false
	}

	var latestFile string
	var latestTime time.Time

	for _, entry := range entries {
		if entry.IsDir() {
			continue
		}
		name := entry.Name()
		if !strings.HasPrefix(name, preTaskFilePrefix) || !strings.HasSuffix(name, ".json") {
			continue
		}

		// Check modification time for nested subagent handling
		info, err := entry.Info()
		if err != nil {
			continue
		}
		if latestFile == "" || info.ModTime().After(latestTime) {
			latestFile = name
			latestTime = info.ModTime()
		}
	}

	if latestFile == "" {
		return "", false
	}

	// Extract tool_use_id from filename: pre-task-<tool_use_id>.json
	toolUseID := strings.TrimPrefix(latestFile, preTaskFilePrefix)
	toolUseID = strings.TrimSuffix(toolUseID, ".json")
	return toolUseID, true
}

// GetNextCheckpointSequence returns the next sequence number for incremental checkpoints.
// It counts existing checkpoint files in the task metadata checkpoints directory.
// Returns 1 if no checkpoints exist yet.
func GetNextCheckpointSequence(sessionID, taskToolUseID string) int {
	// Use the session ID directly as the metadata directory name
	sessionMetadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
	taskMetadataDir := strategy.TaskMetadataDir(sessionMetadataDir, taskToolUseID)
	checkpointsDir := filepath.Join(taskMetadataDir, "checkpoints")

	entries, err := os.ReadDir(checkpointsDir)
	if err != nil {
		// Directory doesn't exist or can't be read - start at 1
		return 1
	}

	// Count JSON files (checkpoints)
	count := 0
	for _, entry := range entries {
		if !entry.IsDir() && strings.HasSuffix(entry.Name(), ".json") {
			count++
		}
	}

	return count + 1
}

package strategy

import (
	"context"
	"io"
	"log/slog"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/format/config"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// truncateStringSlice returns the first n elements of a slice, for concise logging.
func truncateStringSlice(s []string, n int) []string {
	if len(s) <= n {
		return s
	}
	return s[:n]
}

// Content-aware overlap detection for checkpoint management.
//
// These functions determine whether a commit contains session-related work by comparing
// file content (not just filenames) against the shadow branch. This enables accurate
// detection of the "reverted and replaced" scenario where a user:
// 1. Reverts session changes (e.g., git checkout -- file.txt)
// 2. Creates completely different content in the same file
// 3. Commits the new content
//
// In this scenario, the commit should NOT get a checkpoint trailer because the
// session's work was discarded, not incorporated.
//
// The key distinction:
// - Modified files (exist in parent commit): Always count as overlap, regardless of
//   content changes. The user is editing session's work.
// - New files (don't exist in parent): Require content match against shadow branch.
//   If content differs completely, the session's work was likely reverted & replaced.

// overlapOpts provides pre-resolved git objects to avoid redundant reads.
// When fields are non-nil, they are used directly instead of reading from the repo.
type overlapOpts struct {
	headTree      *object.Tree // HEAD commit tree
	shadowTree    *object.Tree // Shadow branch tree
	parentTree    *object.Tree // HEAD's first parent tree (nil = initial commit or not provided)
	hasParentTree bool         // True if parentTree was explicitly resolved (distinguishes nil-not-resolved from nil-initial-commit)
}

// filesOverlapWithContent checks if any file in filesTouched overlaps with the committed
// content, using content-aware comparison to detect the "reverted and replaced" scenario.
//
// This is used in PostCommit to determine if a session has work in the commit.
func filesOverlapWithContent(ctx context.Context, repo *git.Repository, shadowBranchName string, headCommit *object.Commit, filesTouched []string, opts ...overlapOpts) bool {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Use pre-resolved trees if provided, otherwise resolve from repo.
	var o overlapOpts
	if len(opts) > 0 {
		o = opts[0]
	}

	headTree := o.headTree
	if headTree == nil {
		var err error
		headTree, err = headCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesOverlapWithContent: failed to get HEAD tree, falling back to filename check",
				slog.String("error", err.Error()),
			)
			return len(filesTouched) > 0
		}
	}

	shadowTree := o.shadowTree
	if shadowTree == nil {
		refName := plumbing.NewBranchReferenceName(shadowBranchName)
		shadowRef, err := repo.Reference(refName, true)
		if err != nil {
			logging.Debug(logCtx, "filesOverlapWithContent: shadow branch not found, falling back to filename check",
				slog.String("branch", shadowBranchName),
				slog.String("error", err.Error()),
			)
			return len(filesTouched) > 0
		}

		shadowCommit, err := repo.CommitObject(shadowRef.Hash())
		if err != nil {
			logging.Debug(logCtx, "filesOverlapWithContent: failed to get shadow commit, falling back to filename check",
				slog.String("error", err.Error()),
			)
			return len(filesTouched) > 0
		}

		shadowTree, err = shadowCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesOverlapWithContent: failed to get shadow tree, falling back to filename check",
				slog.String("error", err.Error()),
			)
			return len(filesTouched) > 0
		}
	}

	parentTree := o.parentTree
	if parentTree == nil && !o.hasParentTree {
		if headCommit.NumParents() > 0 {
			if parent, err := headCommit.Parent(0); err == nil {
				if pTree, err := parent.Tree(); err == nil {
					parentTree = pTree
				}
			}
		}
	}

	// Check each file in filesTouched
	for _, filePath := range filesTouched {
		// Get file from HEAD tree (the committed content)
		headFile, err := headTree.File(filePath)
		if err != nil {
			// File not in HEAD commit. Check if this is a deletion (existed in parent).
			// Deletions count as overlap because the agent's action (deleting the file)
			// is being committed - we want the session context linked to this commit.
			if parentTree != nil {
				if _, parentErr := parentTree.File(filePath); parentErr == nil {
					// File existed in parent but not in HEAD - this is a deletion
					logging.Debug(logCtx, "filesOverlapWithContent: deleted file counts as overlap",
						slog.String("file", filePath),
					)
					return true
				}
			}
			// File didn't exist in parent either - not a deletion, skip
			continue
		}

		// Check if this is a modified file (exists in parent) or new file
		isModified := false
		if parentTree != nil {
			if _, err := parentTree.File(filePath); err == nil {
				isModified = true
			}
		}

		// Modified files always count as overlap (user edited session's work)
		if isModified {
			logging.Debug(logCtx, "filesOverlapWithContent: modified file counts as overlap",
				slog.String("file", filePath),
			)
			return true
		}

		// For new files, check content against shadow branch
		shadowFile, err := shadowTree.File(filePath)
		if err != nil {
			// File not in shadow branch - this shouldn't happen but skip it
			logging.Debug(logCtx, "filesOverlapWithContent: file in filesTouched but not in shadow branch",
				slog.String("file", filePath),
			)
			continue
		}

		// Compare by hash (blob hash) - exact content match required for new files
		if headFile.Hash == shadowFile.Hash {
			logging.Debug(logCtx, "filesOverlapWithContent: new file content match found",
				slog.String("file", filePath),
				slog.String("hash", headFile.Hash.String()),
			)
			return true
		}

		logging.Debug(logCtx, "filesOverlapWithContent: new file content mismatch (may be reverted & replaced)",
			slog.String("file", filePath),
			slog.String("head_hash", headFile.Hash.String()),
			slog.String("shadow_hash", shadowFile.Hash.String()),
		)
	}

	logging.Debug(logCtx, "filesOverlapWithContent: no overlapping files found",
		slog.Int("files_checked", len(filesTouched)),
	)
	return false
}

// stagedFilesOverlapWithContent checks if any staged file overlaps with filesTouched,
// distinguishing between modified files (always overlap) and new files (check content).
//
// For modified files (already exist in HEAD), we count as overlap because the user
// is editing the session's work. For new files (don't exist in HEAD), we require
// content match to detect the "reverted and replaced" scenario.
//
// This is used in PrepareCommitMsg for carry-forward scenarios.
func stagedFilesOverlapWithContent(ctx context.Context, repo *git.Repository, shadowTree *object.Tree, stagedFiles, filesTouched []string) bool {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Build set of filesTouched for quick lookup
	touchedSet := make(map[string]bool)
	for _, f := range filesTouched {
		touchedSet[f] = true
	}

	// Get HEAD tree to determine if files are being modified or newly created
	head, err := repo.Head()
	if err != nil {
		logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to get HEAD, falling back to filename check",
			slog.String("error", err.Error()),
		)
		return hasOverlappingFiles(stagedFiles, filesTouched)
	}
	headCommit, err := repo.CommitObject(head.Hash())
	if err != nil {
		logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to get HEAD commit, falling back to filename check",
			slog.String("error", err.Error()),
		)
		return hasOverlappingFiles(stagedFiles, filesTouched)
	}
	headTree, err := headCommit.Tree()
	if err != nil {
		logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to get HEAD tree, falling back to filename check",
			slog.String("error", err.Error()),
		)
		return hasOverlappingFiles(stagedFiles, filesTouched)
	}

	// Get the git index to access staged file hashes
	idx, err := repo.Storer.Index()
	if err != nil {
		logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to get index, falling back to filename check",
			slog.String("error", err.Error()),
		)
		return hasOverlappingFiles(stagedFiles, filesTouched)
	}

	// Build a map of index entries for O(1) lookup (avoid O(n*m) nested loop)
	indexEntries := make(map[string]plumbing.Hash, len(idx.Entries))
	for _, entry := range idx.Entries {
		indexEntries[entry.Name] = entry.Hash
	}

	// Check each staged file
	for _, stagedPath := range stagedFiles {
		if !touchedSet[stagedPath] {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: staged file not in files_touched, skipping",
				slog.String("staged_file", stagedPath),
			)
			continue // Not in filesTouched, skip
		}

		// Check if this is a modified file (exists in HEAD) or new file
		_, headErr := headTree.File(stagedPath)
		isModified := headErr == nil

		// Modified files always count as overlap (user edited session's work)
		// This includes deletions - if file exists in HEAD and is being deleted,
		// that's the agent's work being committed.
		if isModified {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: modified file counts as overlap",
				slog.String("file", stagedPath),
			)
			return true
		}

		// For new files, check content against shadow branch
		stagedHash, found := indexEntries[stagedPath]
		if !found {
			continue // Not in index (shouldn't happen but be safe)
		}

		// Get file from shadow branch tree
		shadowFile, err := shadowTree.File(stagedPath)
		if err != nil {
			// File not in shadow branch - can't verify content overlap.
			// Don't assume overlap just because it's in filesTouched.
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: file not in shadow tree, skipping",
				slog.String("file", stagedPath),
			)
			continue
		}

		// Compare hashes - exact match means file is unchanged
		if stagedHash == shadowFile.Hash {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: new file content match found",
				slog.String("file", stagedPath),
				slog.String("hash", stagedHash.String()),
			)
			return true
		}

		// Hashes differ - check if there's significant content overlap.
		// This distinguishes partial staging (user kept some agent content) from
		// "reverted and replaced" (user wrote completely different content).
		shadowContent, shadowErr := shadowFile.Contents()
		if shadowErr != nil {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to read shadow content",
				slog.String("file", stagedPath),
				slog.String("error", shadowErr.Error()),
			)
			continue
		}

		// Read staged content from object store
		stagedBlob, blobErr := repo.BlobObject(stagedHash)
		if blobErr != nil {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to read staged blob",
				slog.String("file", stagedPath),
				slog.String("error", blobErr.Error()),
			)
			continue
		}
		stagedReader, readerErr := stagedBlob.Reader()
		if readerErr != nil {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to get staged reader",
				slog.String("file", stagedPath),
				slog.String("error", readerErr.Error()),
			)
			continue
		}
		stagedBytes, readErr := io.ReadAll(stagedReader)
		_ = stagedReader.Close() // Best effort close
		if readErr != nil {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: failed to read staged content",
				slog.String("file", stagedPath),
				slog.String("error", readErr.Error()),
			)
			continue
		}
		stagedContent := string(stagedBytes)

		// Check for significant content overlap
		if hasSignificantContentOverlap(stagedContent, shadowContent) {
			logging.Debug(logCtx, "stagedFilesOverlapWithContent: new file has partial overlap (partial staging)",
				slog.String("file", stagedPath),
			)
			return true
		}

		logging.Debug(logCtx, "stagedFilesOverlapWithContent: new file has no significant overlap (reverted & replaced)",
			slog.String("file", stagedPath),
			slog.String("staged_hash", stagedHash.String()),
			slog.String("shadow_hash", shadowFile.Hash.String()),
		)
	}

	logging.Debug(logCtx, "stagedFilesOverlapWithContent: no overlapping files found",
		slog.Int("staged_files", len(stagedFiles)),
		slog.Int("files_touched", len(filesTouched)),
		slog.Any("staged_paths", truncateStringSlice(stagedFiles, 10)),
		slog.Any("touched_paths", truncateStringSlice(filesTouched, 10)),
	)
	return false
}

// hasOverlappingFiles checks if any file in stagedFiles appears in filesTouched.
// This is a fallback when content-aware comparison isn't possible.
func hasOverlappingFiles(stagedFiles, filesTouched []string) bool {
	touchedSet := make(map[string]bool)
	for _, f := range filesTouched {
		touchedSet[f] = true
	}

	for _, staged := range stagedFiles {
		if touchedSet[staged] {
			return true
		}
	}
	return false
}

// filesWithRemainingAgentChanges returns files from filesTouched that still have
// uncommitted agent changes. This is used for carry-forward after partial commits.
//
// A file has remaining agent changes if:
//   - It wasn't committed at all (not in committedFiles), OR
//   - It was committed but the committed content doesn't match the shadow branch
//     AND the working tree still has changes (e.g., user did git add -p)
//
// When committed content differs from the shadow but the working tree is clean
// (matches the commit), the user intentionally wrote different content — there
// is nothing left to carry forward.
//
// Falls back to file-level subtraction if shadow branch is unavailable.
func filesWithRemainingAgentChanges(
	ctx context.Context,
	repo *git.Repository,
	shadowBranchName string,
	headCommit *object.Commit,
	filesTouched []string,
	committedFiles map[string]struct{},
	opts ...overlapOpts,
) []string {
	logCtx := logging.WithComponent(ctx, "checkpoint")

	// Use pre-resolved trees if provided, otherwise resolve from repo.
	var o overlapOpts
	if len(opts) > 0 {
		o = opts[0]
	}

	commitTree := o.headTree
	if commitTree == nil {
		var err error
		commitTree, err = headCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get commit tree, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}
	}

	shadowTree := o.shadowTree
	if shadowTree == nil {
		refName := plumbing.NewBranchReferenceName(shadowBranchName)
		shadowRef, err := repo.Reference(refName, true)
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: shadow branch not found, falling back to file subtraction",
				slog.String("branch", shadowBranchName),
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}

		shadowCommit, err := repo.CommitObject(shadowRef.Hash())
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow commit, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}

		shadowTree, err = shadowCommit.Tree()
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: failed to get shadow tree, falling back to file subtraction",
				slog.String("error", err.Error()),
			)
			return subtractFilesByName(ctx, filesTouched, committedFiles)
		}
	}

	// Get worktree root for working tree checks when committed content
	// differs from shadow (distinguishes replacement from partial staging).
	var worktreeRoot string
	if wt, wtErr := repo.Worktree(); wtErr == nil {
		worktreeRoot = wt.Filesystem.Root()
	}

	var remaining []string

	for _, filePath := range filesTouched {
		// Skip files absent from the shadow tree — nothing to carry forward.
		// This covers two cases:
		//  1. Phantom paths: transcript mentions files the agent never created
		//     (e.g. agent writes src/types.go then creates src/types/types.go).
		//  2. Agent deletions: file was deleted on disk, so buildTreeWithChanges
		//     excluded it from the shadow tree. Carrying it forward would be a
		//     no-op since there's no content on disk to snapshot.
		// Without this check, phantom paths cause infinite carry-forward loops.
		shadowFile, err := shadowTree.File(filePath)
		if err != nil {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in shadow tree, skipping",
				slog.String("file", filePath),
			)
			continue
		}

		// File wasn't committed at all — it has remaining changes
		if _, wasCommitted := committedFiles[filePath]; !wasCommitted {
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not committed, keeping",
				slog.String("file", filePath),
			)
			continue
		}

		commitFile, err := commitTree.File(filePath)
		if err != nil {
			// File not in commit tree (deleted?) - keep it if it's in shadow
			remaining = append(remaining, filePath)
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: file not in commit tree but in shadow, keeping",
				slog.String("file", filePath),
			)
			continue
		}

		if commitFile.Hash == shadowFile.Hash {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: content fully committed",
				slog.String("file", filePath),
			)
			continue
		}

		// Committed content differs from shadow. Check whether the working tree
		// still has changes — if clean, the user intentionally replaced the content
		// and there's nothing left to carry forward.
		if worktreeRoot != "" && workingTreeMatchesCommit(worktreeRoot, filePath, commitFile.Hash) {
			logging.Debug(logCtx, "filesWithRemainingAgentChanges: content differs from shadow but working tree is clean, skipping",
				slog.String("file", filePath),
				slog.String("commit_hash", commitFile.Hash.String()[:7]),
				slog.String("shadow_hash", shadowFile.Hash.String()[:7]),
			)
			continue
		}

		remaining = append(remaining, filePath)
		logging.Debug(logCtx, "filesWithRemainingAgentChanges: content mismatch with dirty working tree, keeping for carry-forward",
			slog.String("file", filePath),
			slog.String("commit_hash", commitFile.Hash.String()[:7]),
			slog.String("shadow_hash", shadowFile.Hash.String()[:7]),
		)
	}

	logging.Debug(logCtx, "filesWithRemainingAgentChanges: result",
		slog.Int("files_touched", len(filesTouched)),
		slog.Int("committed_files", len(committedFiles)),
		slog.Int("remaining_files", len(remaining)),
	)

	return remaining
}

// workingTreeMatchesCommit checks if the file on disk matches the committed blob hash.
// Returns true if the working tree is clean for this file (no remaining changes).
func workingTreeMatchesCommit(worktreeRoot, filePath string, commitHash plumbing.Hash) bool {
	absPath := filepath.Join(worktreeRoot, filePath)
	diskContent, err := os.ReadFile(absPath) //nolint:gosec // filePath is from git status, not user input
	if err != nil {
		return false
	}
	of := config.SHA1
	if commitHash.Size() == config.SHA256.Size() {
		of = config.SHA256
	}
	h := plumbing.NewHasher(of, plumbing.BlobObject, int64(len(diskContent)))
	if _, err := h.Write(diskContent); err != nil {
		return false
	}
	return commitHash.Equal(h.Sum())
}

// subtractFilesByName returns files from filesTouched that are NOT in committedFiles.
// This is a fallback when content-aware comparison isn't possible.
func subtractFilesByName(ctx context.Context, filesTouched []string, committedFiles map[string]struct{}) []string {
	logCtx := logging.WithComponent(ctx, "checkpoint")
	logging.Debug(logCtx, "subtractFilesByName: ",
		slog.Any("filesTouched", filesTouched),
		slog.Any("committedFiles", committedFiles),
	)
	var remaining []string
	for _, f := range filesTouched {
		if _, committed := committedFiles[f]; !committed {
			remaining = append(remaining, f)
		}
	}
	return remaining
}

// hasSignificantContentOverlap checks if two file contents share significant lines.
// This distinguishes partial staging (user kept some agent content) from
// "reverted and replaced" (user wrote completely different content).
//
// For larger files, we require at least 2 matching lines because a single match
// (like "package main") is likely common boilerplate. For small files (≤ 2
// significant lines in either file), any single match counts as overlap since
// there aren't many lines to match anyway.
//
// The function filters out trivial lines (short lines < 10 chars like braces,
// empty lines, etc.) because these commonly appear in many files and don't
// indicate meaningful overlap.
func hasSignificantContentOverlap(stagedContent, shadowContent string) bool {
	// Build set of significant lines from shadow (agent) content
	shadowLines := extractSignificantLines(shadowContent)

	// Build set of significant lines from staged (user) content
	stagedLines := extractSignificantLines(stagedContent)

	// If either has no significant lines, no meaningful overlap possible
	if len(shadowLines) == 0 || len(stagedLines) == 0 {
		return false
	}

	// For very small files (0-1 significant lines), any single match is meaningful
	// since requiring 2 matches would be impossible. The 2-line requirement is
	// mainly to filter out coincidental boilerplate (like "package main") in
	// larger files where we CAN require multiple matches.
	isVerySmallFile := len(shadowLines) < 2 || len(stagedLines) < 2
	requiredMatches := 2
	if isVerySmallFile {
		requiredMatches = 1
	}

	// Count matching lines
	matchCount := 0
	for line := range stagedLines {
		if shadowLines[line] {
			matchCount++
			if matchCount >= requiredMatches {
				return true
			}
		}
	}

	return false
}

// extractSignificantLines returns a set of significant lines from content.
// Lines are trimmed and must be at least 10 characters.
//
// This simple length-based filter works well because:
// - Most structural boilerplate is short: `{`, `}`, `});`, `} else {` (all < 10 chars)
// - Long lines (>= 10 chars) are usually meaningful regardless of language
// - No language-specific pattern matching needed
func extractSignificantLines(content string) map[string]bool {
	lines := make(map[string]bool)
	for _, line := range splitLines([]byte(content)) {
		trimmed := trimLine(line)
		if len(trimmed) >= 10 {
			lines[trimmed] = true
		}
	}
	return lines
}

// trimLine removes leading and trailing whitespace from a line.
func trimLine(line string) string {
	start := 0
	end := len(line)
	for start < end && (line[start] == ' ' || line[start] == '\t') {
		start++
	}
	for end > start && (line[end-1] == ' ' || line[end-1] == '\t') {
		end--
	}
	return line[start:end]
}

